function differenceOfSum(nums: number[]): number {
    let [x, y] = [0, 0];
    for (let v of nums) {
        x += v;
        for (; v; v = Math.floor(v / 10)) {
            y += v % 10;
        }
    }
    return x - y;
}

impl Solution {
    pub fn difference_of_sum(nums: Vec<i32>) -> i32 {
        let mut x = 0;
        let mut y = 0;

        for &v in &nums {
            x += v;
            let mut num = v;
            while num > 0 {
                y += num % 10;
                num /= 10;
            }
        }

        x - y
    }
}

int differenceOfSum(int* nums, int numsSize) {
    int x = 0, y = 0;
    for (int i = 0; i < numsSize; i++) {
        int v = nums[i];
        x += v;
        while (v > 0) {
            y += v % 10;
            v /= 10;
        }
    }
    return x - y;
}

class Solution {

private:
    int digits( int num ){

        int sum = 0;

        while(num > 0){

            sum += num % 10;
            num /= 10;

        }

        return sum;
    }



public:
    int differenceOfSum(vector<int>& nums) {

        int elementsum = 0;
        int digitsum = 0;

        for(int i = 0; i < nums.size(); i++){

            if(nums[i] >= 10)
                digitsum += digits(nums[i]);

            else
                digitsum += nums[i];

            elementsum += nums[i];

        }

        return elementsum - digitsum;

    }
};

//Editorial: Just iterate over the array and sum up the values and find the sum of digits of  every values to find the  answer.
class Solution {
public:
    int differenceOfSum(vector<int>& nums) {
        int sum=accumulate(nums.begin(),nums.end(),0);
        int digsum=0;
        for(auto it:nums)
        {
            int temp=it;
            while(temp)
            {
                digsum+=(temp%10);
                temp/=10;
            }
        }
        return abs(sum-digsum);
    }
};
